"use server";
import { revalidatePath } from "next/cache";
import { requireUser } from "@/lib/session";
import { clearCompletedHistory } from "@/lib/history";
import { AppError, type ActionResult } from "@/lib/errors";

export async function deleteHistory(): Promise<
  ActionResult & { cleared?: number }
> {
  const user = await requireUser();
  let cleared: number;
  try {
    cleared = await clearCompletedHistory(user.id);
  } catch (error) {
    return {
      ok: false,
      message:
        error instanceof AppError
          ? error.message
          : "Could not delete history. Please try again.",
    };
  }
  for (const path of ["/settings", "/history", "/compose", "/contacts"])
    revalidatePath(path);
  return {
    ok: true,
    cleared,
    message: cleared
      ? "Completed history deleted."
      : "No completed history to delete.",
  };
}
